// The verified implementation of gcd_i.
//
//   • Precondition:  m > 0 && n > 0.
//   • Postcondition: returns exactly gcd_spec(m, n).
#[requires(m > 0 && n > 0)]
#[ensures(result == gcd_spec(m, n))]
fn gcd_i(m: int, n: int) -> int {
    // keep the runtime check for positive inputs
    assert!(m > 0 && n > 0, "gcd_i requires positive inputs");

    let mut a = m;
    let mut b = n;
    // Loop invariant and termination measure:
    //
    //   1. a and b remain strictly positive.
    //   2. The “logical” gcd of (a, b) stays equal to that of (m, n).
    //   3. The measure (a + b) strictly decreases every iteration.
    #[invariant(a > 0)]
    #[invariant(b > 0)]
    #[invariant(gcd_spec(a, b) == gcd_spec(m, n))]
    #[decreases(a + b)]
    while a != b {
        if a > b {
            a -= b;
        } else {
            b -= a;
        }
    }
    // At exit, a == b, so that common value is the GCD.
    a
}

